module gradient
  implicit none

contains
  function demsav(drdx,c,m,p,flag) result(grad)
    implicit none
    real,dimension(36,66)::drdx
    real,dimension(0:8039)::c
    real,dimension(0:5402)::m
    real,dimension(0:8039)::p
    real::grad
    integer::flag
    ! ::::::::::::::::::::
    real,dimension(0:8039)::dp

    call dbemsav(drdx,dp,m,p,flag)
    grad = dot_product(dp,c)

    return
  end function demsav

  subroutine dbemsav(drdx,dp,m,p,flag)
    implicit none
    real,dimension(36,66),intent(in)::drdx
    real,dimension(0:8039),intent(out)::dp
    real,dimension(0:5402),intent(in)::m
    real,dimension(0:8039),intent(in)::p
    integer::flag
    ! ::::::::::::::::::::
    real,dimension(0:5402)::dm

    call devmono(drdx,dm,m,flag)
    call devpoly(dm,p,dp)

    return
  end subroutine dbemsav

